#[ignore]
fn separate_three_domino_loops() {
    let input: Array<Domino> = array![(1, 2), (2, 3), (3, 1), (4, 5), (5, 6), (6, 4)];
    let none: Option<Array<Domino>> = Option::None;
    assert_eq!(chain(@input), none);
}
